        self.iconAssetToken = iconAssetToken
        self.processingState = processingState
        self.buildAudienceType = buildAudienceType
        self.usesNonExemptEncryption = usesNonExemptEncryption
        self.preReleaseVersionId = preReleaseVersionId
        self.appEncryptionDeclarationId = appEncryptionDeclarationId
        self.betaAppReviewSubmissionId = betaAppReviewSubmissionId
        self.buildBetaDetailId = buildBetaDetailId
        self.versionId = versionId
        self.buildUploadId = buildUploadId
    }
}

public struct PrereleaseVersion: Codable, Sendable, Equatable {
    public let id: String
    public let appId: String
    public let version: String?
    public let platform: String?
    public init(id: String, appId: String, version: String? = nil, platform: String? = nil) {
        self.id = id
        self.appId = appId
        self.version = version
        self.platform = platform
    }
}

